add_action('init',function(){
    foreach(['mm_enquiry'=>['Store enquiries','Store enquiry'],'mm_subscriber'=>['Subscribers','Subscriber']] as $type=>$labels)register_post_type($type,['labels'=>['name'=>$labels[0],'singular_name'=>$labels[1]],'public'=>false,'show_ui'=>true,'show_in_rest'=>false,'supports'=>['title','editor','custom-fields'],'capability_type'=>'post','capabilities'=>['edit_posts'=>'manage_woocommerce','edit_others_posts'=>'manage_woocommerce','publish_posts'=>'manage_woocommerce','read_private_posts'=>'manage_woocommerce','delete_posts'=>'manage_woocommerce','create_posts'=>'do_not_allow'],'map_meta_cap'=>true]);
});
function mm_form_hidden($type){echo '<input type="hidden" name="action" value="mm_'.$type.'">';wp_nonce_field('mm_'.$type,'mm_nonce');echo '<div class="honeypot" aria-hidden="true"><label>Leave empty<input name="website" tabindex="-1" autocomplete="off"></label></div>';}
add_shortcode('mm_newsletter',function(){ob_start();?><form class="mm-ajax-form" method="post" action="<?php echo esc_url(admin_url('admin-ajax.php')); ?>"><?php mm_form_hidden('subscribe'); ?><div class="newsletter-input"><label class="screen-reader-text" for="newsletter-email">Email address</label><input id="newsletter-email" type="email" name="email" placeholder="Your email address" autocomplete="email" maxlength="254" required><button type="submit">Join the edit <span aria-hidden="true">→</span></button></div><label class="consent"><input type="checkbox" name="consent" value="1" required><span>I agree to receive collection updates. Read our <a href="<?php echo esc_url(home_url('/privacy-policy/')); ?>">privacy policy</a>. Withdraw consent through our contact form.</span></label><div role="status" aria-live="polite"></div></form><?php return ob_get_clean();});
add_shortcode('mm_contact',function(){ob_start();?><div class="contact-layout"><div class="contact-copy"><p class="eyebrow">A PERSONAL CONNECTION</p><h2>Good conversations start here.</h2><p>A question about a watch, your order, or finding the right style? Leave us a note.</p><dl class="contact-details"><?php foreach(['support_email'=>'Email','phone'=>'Phone / WhatsApp','hours'=>'Business hours'] as $key=>$label){$value=get_theme_mod('mm_'.$key,'');echo '<dt>'.esc_html($label).'</dt><dd>'.esc_html($value?:'Details to be confirmed before launch.').'</dd>';} ?></dl></div><form class="mm-contact-form mm-ajax-form" method="post" action="<?php echo esc_url(admin_url('admin-ajax.php')); ?>"><?php mm_form_hidden('contact'); ?><div class="form-two"><div><label for="contact-name">Full name *</label><input id="contact-name" name="name" autocomplete="name" maxlength="120" required></div><div><label for="contact-email">Email address *</label><input id="contact-email" type="email" name="email" autocomplete="email" maxlength="254" required></div></div><div><label for="contact-phone">Phone number (optional)</label><input id="contact-phone" type="tel" name="phone" autocomplete="tel" maxlength="40"></div><div><label for="contact-subject">Subject *</label><select id="contact-subject" name="subject" required><option value="">How can we help?</option>Product question</option><option>Order enquiry</option><option>Shipping & returns</option><option>Privacy or unsubscribe request</option><option>Something else</option></select></div><div><label for="contact-message">Your message *</label><textarea id="contact-message" name="message" minlength="10" maxlength="5000" required></textarea></div><label class="consent"><input type="checkbox" name="consent" value="1" required><span>I consent to my details being used to respond to this enquiry, as described in the <a href="<?php echo esc_url(home_url('/privacy-policy/')); ?>">privacy policy</a>.</span></label><button class="button" type="submit">Send your message <span aria-hidden="true">→</span></button><div role="status" aria-live="polite"></div></form></div><?php return ob_get_clean();});
function mm_validate_form($type){
    if(!check_ajax_referer('mm_'.$type,'mm_nonce',false))wp_send_json_error(['message'=>'This form has expired. Refresh the page and try again.'],403);
    if(!empty($_POST['website']))wp_send_json_error(['message'=>'Please leave the website field empty.'],400);
    if(($_POST['consent']??'')!=='1')wp_send_json_error(['message'=>'Please confirm your consent.'],400);
    $email=sanitize_email(wp_unslash($_POST['email']??''));if(!is_email($email))wp_send_json_error(['message'=>'Enter a valid email address.'],400);
    $key='mm_rate_'.hash_hmac('sha256',($_SERVER['REMOTE_ADDR']??'unknown').'|'.$type,wp_salt());$count=(int)get_transient($key);if($count>=8)wp_send_json_error(['message'=>'Please wait a few minutes before trying again.'],429);set_transient($key,$count+1,10*MINUTE_IN_SECONDS);return $email;
}
function mm_submit_subscribe(){
    $email=mm_validate_form('subscribe');$existing=get_posts(['post_type'=>'mm_subscriber','post_status'=>'private','posts_per_page'=>1,'meta_key'=>'_mm_email','meta_value'=>$email]);
    if(!$existing){$id=wp_insert_post(['post_type'=>'mm_subscriber','post_status'=>'private','post_title'=>$email,'post_content'=>'Consent to collection updates recorded '.gmdate('c').'. Source: storefront newsletter. Privacy policy: '.home_url('/privacy-policy/'),'meta_input'=>['_mm_email'=>$email,'_mm_consent_at'=>gmdate('c')]],true);if(is_wp_error($id)||!$id)wp_send_json_error(['message'=>'We could not save your subscription. Please try again.'],500);}
    wp_send_json_success(['message'=>'You are on the list. Your consent has been saved; collection emails will begin when our mailing service is connected.']);
}
function mm_submit_contact(){
    $email=mm_validate_form('contact');$name=sanitize_text_field(wp_unslash($_POST['name']??''));$subject=sanitize_text_field(wp_unslash($_POST['subject']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));$phone=sanitize_text_field(wp_unslash($_POST['phone']??''));
    if(strlen($name)<2||strlen($name)>120||strlen($message)<10||strlen($message)>5000||!in_array($subject,['Product question','Order enquiry','Shipping & returns','Privacy or unsubscribe request','Something else'],true))wp_send_json_error(['message'=>'Please enter your name, choose a subject, and write a message of 10–5,000 characters.'],400);
    $content="From: $name\nEmail: $email\nPhone: $phone\nConsent: ".gmdate('c')."\n\n$message";
    $id=wp_insert_post(wp_slash(['post_type'=>'mm_enquiry','post_status'=>'private','post_title'=>$subject.' — '.$name,'post_content'=>$content,'meta_input'=>['_mm_email'=>$email,'_mm_consent_at'=>gmdate('c')]]),true);
    if(is_wp_error($id)||!$id)wp_send_json_error(['message'=>'We could not save your enquiry. Please try again.'],500);
    $recipient=get_option('mm_notification_email','');if(is_email($recipient)){ $sent=wp_mail($recipient,'New MUNEEB MART enquiry #'.$id,$content,['Reply-To: '.$email]);update_post_meta($id,'_mm_email_notification',$sent?'accepted-by-mailer':'failed'); }
    wp_send_json_success(['message'=>'Thank you. Your enquiry has been received and saved for our store team.']);
}
foreach(['subscribe','contact'] as $type){add_action('wp_ajax_mm_'.$type,'mm_submit_'.$type);add_action('wp_ajax_nopriv_mm_'.$type,'mm_submit_'.$type);}
add_filter('wp_privacy_personal_data_exporters',function($exporters){$exporters['muneeb-mart']=['exporter_friendly_name'=>'MUNEEB MART enquiries and newsletter consent','callback'=>function($email,$page=1){$posts=get_posts(['post_type'=>['mm_enquiry','mm_subscriber'],'post_status'=>'private','meta_key'=>'_mm_email','meta_value'=>$email,'posts_per_page'=>50,'paged'=>$page]);$data=[];foreach($posts as $post)$data[]=['group_id'=>'muneeb-mart','group_label'=>'MUNEEB MART','item_id'=>'mm-'.$post->ID,'data'=>[['name'=>'Record','value'=>$post->post_title],['name'=>'Content','value'=>$post->post_content]]];return ['data'=>$data,'done'=>count($posts)<50];}];return $exporters;});
add_filter('wp_privacy_personal_data_erasers',function($erasers){$erasers['muneeb-mart']=['eraser_friendly_name'=>'MUNEEB MART enquiries and newsletter consent','callback'=>function($email,$page=1){$posts=get_posts(['post_type'=>['mm_enquiry','mm_subscriber'],'post_status'=>'private','meta_key'=>'_mm_email','meta_value'=>$email,'posts_per_page'=>50]);foreach($posts as $post)wp_delete_post($post->ID,true);return ['items_removed'=>(bool)$posts,'items_retained'=>false,'messages'=>[],'done'=>count($posts)<50];}];return $erasers;});
